Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/algorithm/string/split.hpp>
#include <boost/regex.hpp>

std::string markdown_to_html(const std::string& markdown) {
    // On commence par remplacer les balises Markdown par leurs équivalents HTML
    boost::replace_all(markdown, "\\[\\](\\S*)", "<a href=\"$1\">$1</a>");
    boost::replace_all(markdown, "\\`\\S*\\`", "<code>$0</code>");
    boost::replace_all(markdown, "\\*\\S*\\*", "<strong>$0</strong>");
    boost::replace_all(markdown, "_\\S*_", "<em>$0</em>");
    boost::replace_all(markdown, "~~\\S*~~", "<del>$0</del>");
    boost::replace_all(markdown, "\n", "<br>");
    boost::replace_all(markdown, "#", "<h1>");
    boost::replace_all(markdown, "##", "<h2>");
    boost::replace_all(markdown, "###", "<h3>");
    boost::replace_all(markdown, "####", "<h4>");
    boost::replace_all(markdown, "#####", "<h5>");
    boost::replace_all(markdown, "######", "<h6>");
    boost::replace_all(markdown, ">", "&gt;");
    boost::replace_all(markdown, "<", "&lt;");

    // On split le texte en lignes
    std::vector<std::string> lines;
    boost::split(lines, markdown, boost::is_space());

    // On ajoute les balises <p> pour les lignes
    std::string html;
    for (const auto& line : lines) {
        html += "<p>";
        html += line;
        html += "</p>";
    }

    // On retire les balises <p> supplémentaires
    boost::replace_all(html, "<p><br></p>", "<br>");
    boost::replace_all(html, "<p></p>", "");

    return html;
}

int main() {
    std::string markdown = "This is a **bold** text with a [link](https://example.com) and some `code`";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

